// Morphs between the Mandelbrot set and Julia sets. Both repeat z -> z² + c: the Mandelbrot
// set starts at z = 0 with c taken from the pixel, while a Julia set fixes c and starts z at
// the pixel. On the timeline, iFloat0 blends from the Mandelbrot set (0) to a Julia set (1),
// and iFloat1 switches to a second Julia set while the Mandelbrot set is showing.
#define morph iFloat0
#define secondJulia iFloat1
#define ITERATIONS 128
#define AA_SAMPLES 4.0

// A smooth colour palette made from cosine waves.
vec3 palette(float t) {
  vec3 a = vec3(0.5, 0.5, 0.5);
  vec3 b = vec3(0.5, 0.5, 0.2);
  vec3 c = vec3(1.0, 1.0, 0.8);
  vec3 d = vec3(0.8, 0.9, 0.0);
  return a + b * cos(6.28318 * (c * t + d));
}

// Repeats z -> z² + c. Points that escape are coloured by how many steps that took;
// points that never escape are inside the set, and black.
vec3 fractal(vec2 z, vec2 c) {
  for (int i = 1; i <= ITERATIONS; i++) {
    z = vec2(z.x * z.x - z.y * z.y, 2.0 * z.x * z.y) + c;
    if (dot(z, z) > 16.0) {
      return palette(1.58035 + 0.025 * float(i));
    }
  }
  return vec3(0.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  // The Julia set's c: one value, then another once secondJulia switches on.
  vec2 c = mix(vec2(0.4, -0.21), vec2(-0.82, -0.22), secondJulia);

  // Antialiasing: average a sample at the pixel centre and three around it.
  vec3 col = vec3(0.0);
  for (float i = 0.0; i < AA_SAMPLES; i += 1.0) {
    float angle = 6.2831853 / (AA_SAMPLES - 1.0) * i;
    vec2 offset = i < 0.5 ? vec2(0.0) : 0.5 * vec2(sin(angle), cos(angle));
    vec2 uv = (fragCoord + offset) / iResolution;
    // The Mandelbrot set is shifted left to centre it; the Julia set is centred already.
    uv = 4.10763 * (uv - mix(vec2(0.77, 0.5), vec2(0.5), morph));
    col += fractal(mix(vec2(0.0), uv, morph), mix(uv, c, morph));
  }
  fragColor = vec4(col / AA_SAMPLES, 1.0);
}
